7	/// Run lint rules over all deferred for-loops in the [`SemanticModel`].
8	pub(crate) fn deferred_for_loops(checker: &mut Checker) {
9	    while !checker.analyze.for_loops.is_empty() {
10	        let for_loops = std::mem::take(&mut checker.analyze.for_loops);
11	        for snapshot in for_loops {
12	            checker.semantic.restore(snapshot);
13	
14	            let Stmt::For(stmt_for) = checker.semantic.current_statement() else {
15	                unreachable!("Expected Stmt::For");
16	            };
17	            if checker.is_rule_enabled(Rule::UnusedLoopControlVariable) {
18	                flake8_bugbear::rules::unused_loop_control_variable(checker, stmt_for);
19	            }
20	            if checker.is_rule_enabled(Rule::IncorrectDictIterator) {
21	                perflint::rules::incorrect_dict_iterator(checker, stmt_for);
22	            }
23	            if checker.is_rule_enabled(Rule::YieldInForLoop) {
24	                pyupgrade::rules::yield_in_for_loop(checker, stmt_for);
25	            }
26	            if checker.is_rule_enabled(Rule::UnnecessaryEnumerate) {
27	                refurb::rules::unnecessary_enumerate(checker, stmt_for);
28	            }
29	            if checker.is_rule_enabled(Rule::EnumerateForLoop) {
30	                flake8_simplify::rules::enumerate_for_loop(checker, stmt_for);
31	            }
32	            if checker.is_rule_enabled(Rule::LoopIteratorMutation) {
33	                flake8_bugbear::rules::loop_iterator_mutation(checker, stmt_for);
34	            }
35	            if checker.is_rule_enabled(Rule::DictIndexMissingItems) {
36	                pylint::rules::dict_index_missing_items(checker, stmt_for);
37	            }
38	            if checker.is_rule_enabled(Rule::ManualDictComprehension) {
39	                perflint::rules::manual_dict_comprehension(checker, stmt_for);
40	            }
41	            if checker.is_rule_enabled(Rule::ManualListComprehension) {
42	                perflint::rules::manual_list_comprehension(checker, stmt_for);
43	            }
44	        }
45	    }
46	}
